const raw = $json || {};
const body = raw.body || {};
const q = String(body.question || '').trim();
const f = body.step_fields && typeof body.step_fields === 'object' ? body.step_fields : {};
const parts = [];
parts.push('Stap 3 advies (Instrumentkeuze).');
if (f.problem) parts.push('Probleem: ' + String(f.problem));
if (f.causes) parts.push('Oorzaken: ' + String(f.causes));
if (f.symptoms) parts.push('Symptomen: ' + String(f.symptoms));
if (q) parts.push('Vraag: ' + q);
parts.push('Vergelijk minimaal drie instrumentopties op effectiviteit, juridische robuustheid, financiën en uitvoerbaarheid.');
parts.push('Benoem voorkeursoptie en twee alternatieven met risico-afweging.');
return [{ json: { answer: parts.join(' ') } }];
